  PMSP.consumed (PM.p_src s0) (PM.p_src s) sm0 sm = len - w + c ->
  PMSP.src_step (PM.p_src s0) (PM.p_src s) sm0 sm -> fields_eq s -> TX M (PM.p_tb s) (len - w + c) -> PM.mu_src (PM.p_src s) sm < mu0 ->
